    {
      "n": 1,
      "quote": "Cached prompt tokens are billed at 10% of the standard input token price"
    },
    {
      "n": 1,
      "quote": "cache hits can reduce response latency by reusing part of the previous prompt computation"
    },
    {
      "n": 1,
      "quote": "Completion responses report cached prompt tokens in `usage.prompt_tokens_details.cached_tokens`"
    },
    {
      "n": 1,
      "quote": "Set the same `prompt_cache_key` on requests that are likely to share a prefix"
    },
    {
      "n": 3,
      "quote": "Currently, predicted outputs do not impact pricing"
    },
    {
      "n": 2,
      "quote": "Predicted Outputs shine in scenarios where you need to regenerate text documents or code files with minor modifications"
    }
  ],
  "insufficient_evidence": false
}

